        pos[0] += 1
        return c

    def parse_number():
        """Parse a number (possibly negative)."""
        start = pos[0]
        if peek() == '-':
            consume()
        while peek() and peek().isdigit():
            consume()
        return int(s[start:pos[0]])

    def parse_factor():
        """Parse a factor: number or parenthesized expression."""
        if peek() == '(':
            consume()  # consume '('
