    """eval_arith('2+3*4') == 14, eval_arith('(2+4)/3') == 2."""
    # Remove whitespace
    s = s.replace(" ", "")
    pos = [0]  # Use list to allow modification in nested function

    def parse_number():
        """Parse a number (possibly negative) starting at current position."""
        start = pos[0]
        # Handle unary minus
        if s[pos[0]] == '-':
            pos[0] += 1
            # Check if it's a unary minus (start of expression or after operator/paren)
            if pos[0] < len(s) and s[pos[0]].isdigit():
                num = 0
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    num = num * 10 + int(s[pos[0]])
                    pos[0] += 1
                return -num
            else:
                # It's a binary minus, backtrack
                pos[0] = start
                return None
        elif s[pos[0]] == '+':
            pos[0] += 1
            # Handle unary plus
            if pos[0] < len(s) and s[pos[0]].isdigit():
                num = 0
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    num = num * 10 + int(s[pos[0]])
                    pos[0] += 1
                return num
            else:
                pos[0] = start
                return None

        num = 0
        while pos[0] < len(s) and s[pos[0]].isdigit():
            num = num * 10 + int(s[pos[0]])
            pos[0] += 1
        return num

