{"path": "solution.py", "content": "def add_days(date_str, n):
    """add_days('2026-01-31', 3) == '2026-02-03'."""
    year, month, day = map(int, date_str.split('-'))

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_in_month(y, m):
        if m == 2:
            return 29 if is_leap(y) else 28
        elif m in [4, 6, 9, 11]:
            return 30
        else:
            return 31

    # Add n days
    day += n

    # Handle positive overflow (day exceeds days in current month)
    while day > days_in_month(year, month):
        day -= days_in_month(year, month)
        month += 1
        if month > 12:
            month = 1
            year += 1

    # Handle negative underflow (day goes below 1)
    while day < 1:
        month -= 1
        if month < 1:
            month = 12
            year -= 1
        day += days_in_month(year, month)

    return f"{year}-{month:02d}-{day:02d}""}

