    """Evaluate an integer arithmetic expression with + - * / and parentheses.

    '/' is integer division (floor).  No use of eval() -- this is a
    recursive-descent parser over the following grammar:

        expr   := term (('+' | '-') term)*
        term   := factor (('*' | '/') factor)*
        factor := ('+' | '-') factor | atom
        atom   := NUMBER | '(' expr ')'
    """
    if not isinstance(s, str):
        raise TypeError("eval_arith expects a string expression")

    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("empty expression")

    pos = [0]  # mutable cursor shared by the parser helpers

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = peek()
        pos[0] += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                value = value + rhs
            else:
                value = value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("integer division by zero")
                # floor division (Python's // already floors toward -inf)
                value = value // rhs
        return value

    def parse_factor():
        tok = peek()
        if tok == '+':
            advance()
            return parse_factor()
        if tok == '-':
            advance()
            return -parse_factor()
        return parse_atom()

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return value
        if isinstance(tok, int):
            advance()
            return tok
        raise ValueError("unexpected token: %r" % (tok,))

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("unexpected token: %r" % (peek(),))
    return result


def _tokenize(s):
    """Turn the input string into a list of ints and operator/paren chars."""
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("invalid character in expression: %r" % (ch,))
    return tokens
