    expr   := term (('+' | '-') term)*
    term   := factor (('*' | '/') factor)*
    factor := ('+' | '-') factor | '(' expr ')' | INTEGER

'/' is integer division that floors toward negative infinity (Python's //).
No use of eval().
"""


def eval_arith(s):
    """Evaluate an integer arithmetic expression string.

    eval_arith('2+3*4') == 14, eval_arith('(2+4)/3') == 2.
    """
    if not isinstance(s, str):
        raise TypeError("expression must be a string")

    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("empty expression")

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = peek()
        pos[0] += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            op = advance()
            rhs = parse_term()
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() in ("*", "/"):
            op = advance()
            rhs = parse_factor()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("integer division by zero")
                value = value // rhs  # floor division
        return value

    def parse_factor():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok == "+":
            advance()
            return parse_factor()
        if tok == "-":
            advance()
            return -parse_factor()
        if tok == "(":
            advance()
            value = parse_expr()
            if peek() != ")":
                raise ValueError("missing closing parenthesis")
            advance()
            return value
        if isinstance(tok, int):
            advance()
            return tok
        raise ValueError("unexpected token: %r" % (tok,))

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("unexpected token: %r" % (tokens[pos[0]],))
    return result


def _tokenize(s):
    """Convert a string into a list of tokens (ints and operator symbols)."""
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        elif ch in "+-*/()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("invalid character in expression: %r" % (ch,))
    return tokens

