{"path": "solution.py", "content": "def _is_leap(y):
    """Proleptic Gregorian leap year rule."""
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


_MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def _days_in_month(y, m):
    if m == 2 and _is_leap(y):
        return 29
    return _MONTH_DAYS[m - 1]


def _days_in_year(y):
    return 366 if _is_leap(y) else 365


def _to_ordinal(y, m, d):
    """Number of days since 0001-01-01 (which is day 1). Valid for y >= 1."""
    # Days contributed by all complete years before year y.
    yy = y - 1
    total = 365 * yy + yy // 4 - yy // 100 + yy // 400
    # Days contributed by complete months of year y.
    for mm in range(1, m):
        total += _days_in_month(y, mm)
    return total + d


def _from_ordinal(n):
    """Inverse of _to_ordinal (n >= 1)."""
    # Estimate a year, then correct.
    y = max(1, n // 366)
    while _to_ordinal(y, 1, 1) > n:
        y -= 1
    while _to_ordinal(y + 1, 1, 1) <= n:
        y += 1
    # Remaining days within year y (1-based day of year).
    rem = n - _to_ordinal(y, 1, 1) + 1
    m = 1
    while rem > _days_in_month(y, m):
        rem -= _days_in_month(y, m)
        m += 1
    return y, m, rem


def add_days(date_str, n):
    """add_days('2026-01-31', 3) == '2026-02-03'."""
    parts = date_str.split("-")
    y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
    n = int(n)

    if y >= 1:
        target = _to_ordinal(y, m, d) + n
    else:
        target = None

    if target is not None and target >= 1:
        ny, nm, nd = _from_ordinal(target)
    else:
        # Fallback (extremely rare: dates at/before year 1 going further back):
        # step one day at a time.
        ny, nm, nd = y, m, d
        step = 1 if n > 0 else -1
        for _ in range(abs(n)):
            nd += step
            if nd > _days_in_month(ny, nm):
                nd = 1
                nm += 1
                if nm > 12:
                    nm = 1
                    ny += 1
            elif nd < 1:
                nm -= 1
                if nm < 1:
                    nm = 12
                    ny -= 1
                nd = _days_in_month(ny, nm)

    return "%04d-%02d-%02d" % (ny, nm, nd)
"}

