        while pos[0] < n and s[pos[0]].isspace():
            pos[0] += 1

    def peek():
        skip_ws()
        if pos[0] < n:
            return s[pos[0]]
        return None

    def consume():
        ch = peek()
        if ch is not None:
            pos[0] += 1
        return ch

    def parse_expr():
        # Addition / subtraction (lowest precedence)
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # Multiplication / division (higher precedence)
        left = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = left // right  # integer division (floor)
        return left

    def parse_factor():
        ch = peek()

