    """Days elapsed since 0001-01-01 (that day itself is ordinal 1)."""
    return _days_before_year(year) + _days_before_month(year, month) + day


def _from_ordinal(n):
    """Inverse of _to_ordinal: return (year, month, day) for ordinal `n`."""
    # 400 years == 146097 days, so this estimate is within ~1 year.
    year = 1 + (n - 1) * 400 // 146097
    # Correct the estimate (monotonic, so the loops terminate quickly).
    while _to_ordinal(year, 1, 1) > n:
