    Adds n days (n may be negative) to a 'YYYY-MM-DD' date and returns the
    resulting date in the same format. Pure calendar arithmetic, no imports.
    """
    _MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

    def is_leap(y):
        # Divisible by 4, except centuries unless divisible by 400.
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        if m == 2 and is_leap(y):
            return 29
        return _MONTH_DAYS[m - 1]

    def days_before_year(y):
        # Number of days in all years strictly before year y (proleptic
        # Gregorian), i.e. days from 0001-01-01 back to Jan 1 of year y.
        yy = y - 1
        return yy * 365 + yy // 4 - yy // 100 + yy // 400

    def to_ordinal(y, m, d):
        # Day number where 0001-01-01 is day 1.
        total = days_before_year(y)
        for mm in range(1, m):
            total += days_in_month(y, mm)
        return total + d

    def from_ordinal(total):
        # Inverse of to_ordinal: day number -> (year, month, day).
        # Start from a safe lower-bound estimate for the year.
        y = total // 366 + 1
        if y < 1:
            y = 1
        while days_before_year(y + 1) < total:
            y += 1
        rem = total - days_before_year(y)
        m = 1
        while rem > days_in_month(y, m):
            rem -= days_in_month(y, m)
            m += 1
        return y, m, rem

    # ---- parse input ----
    parts = date_str.strip().split("-")
    if len(parts) != 3:
        raise ValueError("date must be in 'YYYY-MM-DD' format: %r" % (date_str,))
    y, m, d = int(parts[0]), int(parts[1]), int(parts[2])

    if not (1 <= m <= 12):
        raise ValueError("month out of range: %r" % (date_str,))
    if not (1 <= d <= days_in_month(y, m)):
        raise ValueError("day out of range: %r" % (date_str,))

    total = to_ordinal(y, m, d) + n
    if total < 1:
        raise ValueError("resulting date is before 0001-01-01")

    y2, m2, d2 = from_ordinal(total)
    return "%04d-%02d-%02d" % (y2, m2, d2)

